begin;
create extension if not exists pgtap with schema extensions;
set local search_path to public,extensions;
select plan(21);
insert into auth.users(id,email) values('30000000-0000-0000-0000-000000000001','payments-owner@example.test'),('30000000-0000-0000-0000-000000000002','payments-other@example.test');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"30000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select public.create_business('Payment test','','{plumbing}','flat',0);
reset role;
create temp table payment_fixture as select business_id as bid,'30000000-0000-0000-0000-000000000003'::uuid as job from public.business_members where user_id='30000000-0000-0000-0000-000000000001';
grant select on payment_fixture to authenticated;
update public.businesses set alternative_methods='{"cash":""}' where id=(select bid from payment_fixture);
insert into public.customers(id,business_id,name) select '30000000-0000-0000-0000-000000000004',bid,'Customer' from payment_fixture;
insert into public.jobs(id,business_id,customer_id,title) select job,bid,'30000000-0000-0000-0000-000000000004','Bathroom' from payment_fixture;
insert into public.estimates(id,business_id,job_id,number,deposit_bps) select '30000000-0000-0000-0000-000000000005',bid,job,'E-TEST',3000 from payment_fixture;
insert into public.estimate_lines(business_id,estimate_id,description,unit,qty_hundredths,unit_cents) select bid,'30000000-0000-0000-0000-000000000005','Bathroom','flat',100,100000 from payment_fixture;
update public.estimates set sent_at=now(),tax_rate_bps=0,tax_labor=false,tax_materials=false where id='30000000-0000-0000-0000-000000000005';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"30000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select public.sign_estimate(job,'Customer','test','[[[0,0],[1,1]]]') from payment_fixture;
select lives_ok($$select public.create_job_payment_request('30000000-0000-0000-0000-000000000006',job,'deposit',1,'Deposit') from payment_fixture$$,'owner can request signed deposit');
select is((select amount_cents from public.job_payment_requests),30000,'deposit amount is derived on server, ignoring supplied amount');
select is((select count(*)::int from public.payments),0,'request is not a payment');
select lives_ok($$select public.create_job_payment_request('30000000-0000-0000-0000-000000000006',job,'deposit',1,'Deposit') from payment_fixture$$,'same request UUID retries safely');
select throws_ok($$select public.create_job_payment_request('30000000-0000-0000-0000-000000000007',job,'milestone',80000,'Too much') from payment_fixture$$,'P0001','Amount exceeds the agreed job total','milestones cannot overbook agreed amount');
select lives_ok($$select public.record_job_cash('30000000-0000-0000-0000-000000000006')$$,'owner confirms cash');
select lives_ok($$select public.record_job_cash('30000000-0000-0000-0000-000000000006')$$,'cash confirmation retries safely');
select is((select count(*)::int from public.payments),1,'retry does not duplicate money');
select is((select sum(amount_cents)::int from public.payments where status='succeeded'),30000,'only confirmed deposit is credited');
select lives_ok($$insert into public.change_orders(id,business_id,job_id,number,description,amount_cents,base_cents,sent_at) select '30000000-0000-0000-0000-000000000008',bid,job,1,'Credit for removed fixture',-10000,100000,now() from payment_fixture$$,'credit variation can reduce unpaid agreed balance');
select lives_ok($$select public.sign_change_order('30000000-0000-0000-0000-000000000008','Customer','test','[[[0,0],[1,1]]]')$$,'credit can be approved');
reset role;
select is(public.job_agreed_total((select job from payment_fixture)),90000,'approved credit reduces agreed total');
set local role authenticated;
insert into public.invoices(id,business_id,job_id,number) select '30000000-0000-0000-0000-000000000009',bid,job,'I-FINAL' from payment_fixture;
insert into public.invoice_lines(business_id,invoice_id,description,kind,qty_hundredths,unit_cents) select bid,'30000000-0000-0000-0000-000000000009','Agreed work','labor',100,100000 from payment_fixture;
select lives_ok($$insert into public.invoice_lines(business_id,invoice_id,description,kind,qty_hundredths,unit_cents) select bid,'30000000-0000-0000-0000-000000000009','Approved credit','fee',100,-10000 from payment_fixture$$,'final invoice retains negative credit line');
update public.invoices set sent_at=now(),tax_rate_bps=0,tax_labor=false,tax_materials=false,issued_on=current_date,due_days=0 where id='30000000-0000-0000-0000-000000000009';
select throws_ok($$select public.mark_invoice_paid('30000000-0000-0000-0000-000000000009',90000)$$,'P0001','Balance changed. Refresh first','stale full amount cannot charge already received deposit twice');
select lives_ok($$select public.mark_invoice_paid('30000000-0000-0000-0000-000000000009',60000)$$,'final cash records only remaining balance');
select lives_ok($$select public.mark_invoice_paid('30000000-0000-0000-0000-000000000009',60000)$$,'lost final cash acknowledgement can retry');
select is((select count(*)::int from public.payments),2,'one deposit and one final payment, no duplicate cash');
select is((select sum(amount_cents)::int from public.payments where status='succeeded'),90000,'deposit plus final cash equals credited job total exactly');
select set_config('request.jwt.claims','{"sub":"30000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
select is((select count(*)::int from public.job_payment_requests),0,'another account cannot see requests');
select throws_ok($$select public.record_job_cash('30000000-0000-0000-0000-000000000006')$$,'P0001','Not allowed','another account cannot record cash');
select throws_ok($$select public.reserve_job_payment('30000000-0000-0000-0000-000000000006','wallet')$$,'42501',null,'app cannot invoke Stripe-only payment reservation');
select * from finish();
rollback;
